from itertools import product
shapes=set()
for flip in [False,True]:
 for rot in range(4):
  pts=[]
  for r,c in marker:
   x,y=int(r),int(c-2)
   if flip:y=-y
   for _ in range(rot): x,y=y,-x
   pts.append((x,y))
  mnx=min(x for x,y in pts); mny=min(y for x,y in pts)
  shapes.add(tuple(sorted((x-mnx,y-mny) for x,y in pts)))
hits=set()
for shape in shapes:
 h=max(x for x,y in shape)+1; w=max(y for x,y in shape)+1
 for r in range(16-h+1):
  for c in range(25-w+1):
   if all(arr[r+x,c+y]==0 for x,y in shape):hits.update((r+x,c+y) for x,y in shape)
len(hits),sorted(hits)

# count exact original orientation hits
sh=tuple(sorted((int(r),int(c-2)) for r,c in marker)); h=max(x for x,y in sh)+1; w=max(y for x,y in sh)+1
orig=[]
for r in range(16-h+1):
 for c in range(25-w+1):
  if all(arr[r+x,c+y]==0 for x,y in sh):orig.append((r,c))
orig

